package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.io.*;
public final class PcWorldReferenceExport {
 static void buffer(DataOutputStream out,ByteBuffer b)throws Exception{int n=b==null?0:b.remaining();out.writeInt(n);if(n!=0){byte[] raw=new byte[n];b.get(raw);out.write(raw);}}
 static ByteBuffer identity(long[] v){ByteBuffer b=ByteBuffer.allocate(20).order(ByteOrder.LITTLE_ENDIAN);for(long x:v)b.putInt((int)x);b.flip();return b;}
 static int export(Path output,String name,NativeScenePacket packet)throws Exception{NativeWorldScene world=new NativeWorldScene(packet);ByteBuffer raw=packet.data();byte[] bytes=new byte[raw.remaining()];raw.get(bytes);Files.write(output.resolve(name+".nsp"),bytes);try(DataOutputStream out=new DataOutputStream(Files.newOutputStream(output.resolve(name+".reference")))){out.writeInt(world.surfaceCount());out.writeInt(world.modelCount);out.writeInt(world.commandCount());for(int i=0;i<world.surfaceCount();i++){NativeWorldScene.Surface s=world.surface(i);NativeDrawBounds b=NativeDrawBounds.command(world.bounds(),world.surfaceCount(),false,i);int order=-1;for(int c=0;c<world.commandCount();c++){NativeWorldScene.Command command=world.command(c);if(!command.model&&command.index==i)order=c;}if(order<0)throw new AssertionError();long[] info={s.corners,s.width,s.height,s.kind,s.mode,s.lit?1:0,s.planes,b.left,b.right,b.top,b.bottom,order};for(long value:info)out.writeLong(value);for(ByteBuffer buf:new ByteBuffer[]{s.vertices(),s.uv(),s.texture(),s.metadata(),s.lighting(),s.states(),s.originalIndices(),s.sourceAttributes(),s.sourceCamera(),identity(s.identity())})buffer(out,buf);}buffer(out,world.reciprocal());buffer(out,world.bounds());buffer(out,packet.section(2));for(int c=0;c<world.commandCount();c++){NativeWorldScene.Command command=world.command(c);out.writeLong(command.model?1:0);out.writeLong(command.index);}}return world.surfaceCount();}
 public static void main(String[] args)throws Exception{Path output=Paths.get(args[1]);Files.createDirectories(output);int frames=0,owners=0,surfaces=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(Paths.get(args[0]),"source-race-background-*.nrb")){for(Path file:files){NativeSceneSnapshot scene=new NativeBackgroundScene(Files.readAllBytes(file)).sky.scene;for(int owner=0;owner<scene.geometryCount();owner++){surfaces+=export(output,scene.refresh+"-"+owner,scene.geometry(owner));owners++;}frames++;}}if(args.length>2)try(DirectoryStream<Path> files=Files.newDirectoryStream(Paths.get(args[2]),"*.nsp")){for(Path file:files){surfaces+=export(output,file.getFileName().toString().replace(".nsp",""),new NativeScenePacket(1,Files.readAllBytes(file)));owners++;}}System.out.println("PASS_PC_WORLD_JAVA_EXPORT frames="+frames+" owners="+owners+" surfaces="+surfaces);}
}
